+function expandToggle(): HTMLButtonElement {
+  return document.querySelector('[data-slot="zoom"]') as HTMLButtonElement
 }

+/** 카드 안을 통째로 본다. 넓힌 카드의 설명과 담긴 종목이 모두 이 안에 있다. */
